let route='home',lessonId=1,labTab='balance',sourceTab='pages',reviewTab='qa',sourceId='citi',sourcePage=1,modalSource='citi',modalPage=1,completed=new Set(),lastLesson=1,matrixRow=0,matrixCol=2;
try {completed=new Set(JSON.parse(localStorage.getItem('memory-course-completed')||'[]'));lastLesson=Number(localStorage.getItem('memory-course-last')||1);if(lastLesson<1||lastLesson>24)lastLesson=1;}catch(e){}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const signed=(v,d=1)=>(v>0?'+':'')+Number(v).toFixed(d)+'%';
function ref(s,p){return `<button class="pill" data-source="${s}" data-page="${p}">${srcName[s]} · p.${p} ↗</button>`}
function refs(r){return `<div class="pillrow">${r.map(x=>ref(...x)).join('')}</div>`}
function chart(key,caption=''){return `<figure class="chartbox"><img src="${A.charts[key]}" alt="${esc(caption||key)}" loading="lazy"><figcaption class="caption">${esc(caption)}</figcaption></figure>`}
function table(t){return `<div class="tablewrap"><table><thead><tr>${t.heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function progress(){document.getElementById('progressText').textContent=`${completed.size} / 24`;document.getElementById('progressFill').style.width=`${completed.size/24*100}%`}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function navigate(r){route=r;document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.route===r));if(r==='home')home();if(r==='course')course();if(r==='labs')labs();if(r==='sources')sources();if(r==='review')review();window.scrollTo(0,0)}
function gotoLesson(n){lessonId=n;lastLesson=n;try{localStorage.setItem('memory-course-last',String(n))}catch(e){}navigate('course')}
function home(){
 app.innerHTML=`<div class="hero"><div><div class="eyebrow">THREE PERSPECTIVES · ONE MEMORY CYCLE</div><h1>存储周期的<br>三重视角</h1><p class="intro">从 AI 如何学习，走到价格如何形成，再看中国供给怎样改变竞争。沿着三份原始研报，把产品、需求、产能和周期放在一起理解。</p><div class="actions"><button class="btn" id="startLearning">${completed.size?'继续学习':'从第一课开始'} <span>→</span></button><button class="btn ghost" data-route="sources">查看三份原文</button></div></div><div class="hero-art"><div class="lens-orbit"><div class="orbit-ring"></div><div class="orbit-ring inner"></div><div class="orbit-center">存储周期<small>DEMAND · PRICE · SUPPLY</small></div><div class="orbit-label one"><strong>需求</strong>CITI</div><div class="orbit-label two"><strong>价格</strong>BERNSTEIN</div><div class="orbit-label three"><strong>供给</strong>MORGAN STANLEY</div></div></div></div><div class="counts"><div class="count"><b>24</b><span>由浅入深的课程</span></div><div class="count"><b>89</b><span>原图表中文导读</span></div><div class="count"><b>75</b><span>完整原文页面</span></div><div class="count"><b>3</b><span>可交互实验</span></div></div><div class="section-title"><h2>按六个单元，建立判断</h2><small>先理解，再推演</small></div><div class="pathlist">${C.units.map((u,i)=>`<button class="pathrow" data-lesson="${u[2]}"><span class="pathnum">0${i+1}</span><div><h3>${u[0]}</h3><p>${u[1]}</p></div><span class="range">第 ${u[2]}—${u[3]} 课</span><span>↗</span></button>`).join('')}</div><div class="section-title"><h2>原始研究，始终在旁</h2><small>所有预测保留机构与时间</small></div><div class="sourcecards">${C.sources.map(s=>`<button class="sourcecard" data-source="${s.id}" data-page="1"><small>${s.date}</small><h3>${s.name}</h3><p>${s.short}</p><div class="sourcefoot">${s.pages} 页原文 / ${s.figures} 幅编号图表 ↗</div></button>`).join('')}</div><div class="scope-note">材料依据所附三份报告编制，不引入外部行情更新。中文课程为忠实转述、概念解释与教学整理；原报告 75 页（包括披露）完整可查，并非逐字全文翻译。供需表、图表和正文存在的数值差异，统一在第23课及核验记录中保留。</div>`;
 document.getElementById('startLearning').onclick=()=>gotoLesson(completed.size?lastLesson:1);
}
function course(){let l=C.lessons[lessonId-1];let unit=C.units.find(u=>lessonId>=u[2]&&lessonId<=u[3]);
 app.innerHTML=`<div class="lesson-layout"><aside class="lesson-nav" aria-label="课程目录">${C.units.map((u,i)=>`<details ${lessonId>=u[2]&&lessonId<=u[3]?'open':''}><summary>0${i+1} · ${u[0]}</summary>${C.lessons.filter(x=>x.id>=u[2]&&x.id<=u[3]).map(x=>`<button class="${x.id===lessonId?'current':''}" data-lesson="${x.id}">${String(x.id).padStart(2,'0')} ${x.title}${completed.has(x.id)?'<span class="tick">✓</span>':''}</button>`).join('')}</details>`).join('')}</aside><article><header class="lesson-head"><div class="eyebrow">${unit[0]} / LESSON ${String(l.id).padStart(2,'0')}</div><h1>${l.title}</h1><div class="question">${l.question}</div></header><div class="bodytext">${l.paras.map(p=>`<p>${esc(p)}</p>`).join('')}</div>${refs(l.refs)}${chart(l.visual,chartCaption(l))}${l.table?table(l.table):''}${[7,10,12,16,20,23].includes(l.id)?`<button class="btn secondary" id="openLab">在实验室复算 ${l.id===20?'供需分界':'这一逻辑'} ↗</button>`:''}<section class="advanced"><h3>进阶研读 / 检查结论的边界</h3><p>${esc(l.advanced)}</p></section>${l.id===23?'<div style="margin-top:20px"><button class="btn ghost" id="showAudit">打开全部核验记录 ↗</button></div>':''}<footer class="lessonfoot"><button class="btn ghost" data-lesson="${Math.max(1,l.id-1)}" ${l.id===1?'disabled':''}>← 上一课</button><button class="btn secondary" id="completeLesson">${completed.has(l.id)?'✓ 已完成本课':'标记已完成'}</button><button class="btn" data-lesson="${Math.min(24,l.id+1)}" ${l.id===24?'disabled':''}>下一课 →</button></footer></article></div>`;
 document.getElementById('completeLesson').onclick=()=>{if(completed.has(l.id))completed.delete(l.id);else completed.add(l.id);try{localStorage.setItem('memory-course-completed',JSON.stringify([...completed]))}catch(e){}progress();course();toast(completed.has(l.id)?'已记录本课学习进度':'已取消完成标记')};
 let lab=document.getElementById('openLab');if(lab)lab.onclick=()=>{labTab=l.id===20?'matrix':l.id===16||l.id===7?'despec':'balance';navigate('labs')};
 let audit=document.getElementById('showAudit');if(audit)audit.onclick=()=>{reviewTab='audit';navigate('review')};
}
function chartCaption(l){const notes={hbm:'Citi p13 图26；bn Gb；2026—2028年均为机构预测。',dram_sd:'Citi p11 图20；由原始供需水平重绘，增速差异见第23课。',nand_sd:'Citi p17 图36；单位为bn个8Gb等效单位，增速差异见第23课。',scenario:'Morgan Stanley p12 图20；负值为不足、正值为过剩，固定其余假设。',compare:'Citi p13 图26；Morgan Stanley p5 图8；报告日期、模型假设不同。',capex:'Citi p18 图40—42；十亿美元；远期值为模型预测，分项与总表有尾差。',cxmt:'Morgan Stanley p4 图3；KWPM；2026年及以后为预测。',dram_prices:'Bernstein p1、p4；2026年8月数据所指向的Q3判断，四项为报告概述值。',nand_prices:'Bernstein p6 图2；8月现货月环比，不能等同合约或SSD涨幅。',dies:'Citi p9 图12；原图列示的每晶圆die数，不等于合格stack产出。',nand_layers:'Citi p14；企业级SSD与全部SSD的不同产品范围，均为2027年预测。',price_scope:'Bernstein p5—6；直接样本与综合估计范围不同，20%是“接近20%”的示意值。',ymtc:'Morgan Stanley p11；报告所引用的产品指标，不表示已获得广泛客户认证。',history:'Morgan Stanley p8 图13；关键厂商数量口径。'};return notes[l.visual]||'依据本课所列原文制作的教学示意；请结合正文和原图理解。'}
function labs(){app.innerHTML=`<header class="pagehead"><div class="eyebrow">SCENARIO LAB</div><h1>改变条件，观察结论</h1><p>原表能算出的结果直接复现；自行改变参数的部分明确标为教学情景。用三个小实验，理解模型为何会得到不同判断。</p></header><div class="segmented">${[['balance','供需模型'],['matrix','2028 NAND 矩阵'],['despec','降配与总需求']].map(x=>`<button data-lab="${x[0]}" class="${labTab===x[0]?'selected':''}">${x[1]}</button>`).join('')}</div><section id="labContent"></section>`;if(labTab==='balance')balanceLab();if(labTab==='matrix')matrixLab();if(labTab==='despec')despecLab()}
function balanceLab(){document.getElementById('labContent').innerHTML=`<div class="labbox"><h2>供需比，先从原表复算</h2><p class="lede">先选产品和年份，再观察供给或需求偏离原预测时，缺口怎样变化。</p><div class="lab-controls"><div class="control"><label for="material">产品口径</label><select id="material"><option value="dram">DRAM · Citi 图20</option><option value="nand">NAND · Citi 图36</option><option value="hbm">HBM · Citi 图26</option></select></div><div class="control"><label for="year">预测年份</label><select id="year"><option value="0">2026E</option><option value="1" selected>2027E</option><option value="2">2028E</option></select></div></div><div class="lab-controls"><div class="control"><div class="slider-title"><label for="supplyAdj">供给相对原预测调整</label><output id="supplyAdjVal">0%</output></div><input id="supplyAdj" aria-label="供给调整百分比" type="range" min="-30" max="30" value="0" step="1"></div><div class="control"><div class="slider-title"><label for="demandAdj">需求相对原预测调整</label><output id="demandAdjVal">0%</output></div><input id="demandAdj" aria-label="需求调整百分比" type="range" min="-30" max="30" value="0" step="1"></div></div><div class="outcomes"><div><small>原表供需比 · 复算</small><strong id="baselineRatio"></strong><em>由原表供给和需求计算</em></div><div><small>教学情景供需比</small><strong id="scenarioRatio"></strong><em id="scenarioState"></em></div><div><small>相对原表变化</small><strong id="deltaRatio"></strong><em>百分点</em></div></div><div class="lab-bars"><div><div class="lab-bar-head"><span>供给</span><span id="supplyNum"></span></div><div class="bar-track"><div id="supplyBar" class="bar-fill"></div></div></div><div><div class="lab-bar-head"><span>需求</span><span id="demandNum"></span></div><div class="bar-track"><div id="demandBar" class="bar-fill gold"></div></div></div></div><div class="formula" id="balanceFormula"></div><div class="lab-foot">调整代表相对当年原预测水平的变化，属于教学扰动；不是机构新增预测，也不是同比增速。原表供需比按未取整数值复算，可能与印刷表的取整值略有不同。</div><div class="actions" style="margin-top:18px"><button class="btn ghost" id="resetBalance">恢复原表</button><span id="balanceSource"></span></div></div>`;
 for(const id of ['material','year','supplyAdj','demandAdj'])document.getElementById(id).addEventListener('input',updateBalance);document.getElementById('resetBalance').onclick=()=>{document.getElementById('supplyAdj').value=0;document.getElementById('demandAdj').value=0;updateBalance()};updateBalance()}
function updateBalance(){let kind=document.getElementById('material').value,i=+document.getElementById('year').value,sa=+document.getElementById('supplyAdj').value,da=+document.getElementById('demandAdj').value;let d=C.data[kind],s=d.supply[i],q=d.demand[i],ns=s*(1+sa/100),nq=q*(1+da/100),base=(s/q-1)*100,r=(ns/nq-1)*100;document.getElementById('supplyAdjVal').textContent=signed(sa,0);document.getElementById('demandAdjVal').textContent=signed(da,0);document.getElementById('baselineRatio').textContent=signed(base,2);document.getElementById('scenarioRatio').textContent=signed(r,2);document.getElementById('deltaRatio').textContent=(r-base>=0?'+':'')+(r-base).toFixed(2);document.getElementById('scenarioState').textContent=Math.abs(r)<.05?'表内接近平衡':r<0?'供给不足':'供给过剩';let unit=kind==='nand'?'bn个8Gb等效单位':'bn Gb';document.getElementById('supplyNum').textContent=fmt(ns/1000,3)+' '+unit;document.getElementById('demandNum').textContent=fmt(nq/1000,3)+' '+unit;let max=Math.max(ns,nq)*1.07;document.getElementById('supplyBar').style.width=ns/max*100+'%';document.getElementById('demandBar').style.width=nq/max*100+'%';document.getElementById('balanceFormula').textContent=`原表：${fmt(s,0)} ÷ ${fmt(q,0)} − 1 = ${signed(base,2)}；调整后：${fmt(ns,0)} ÷ ${fmt(nq,0)} − 1 = ${signed(r,2)}。`;document.getElementById('balanceSource').innerHTML=ref('citi',kind==='dram'?11:kind==='nand'?17:13)}
function matrixLab(){let m=C.data.matrix;document.getElementById('labContent').innerHTML=`<div class="labbox"><h2>2028 年 NAND：供给与需求的分界</h2><p class="lede">点击任意格点，比较长江存储产能与 AI SSD 增长组合。全部36个值逐格来自大摩原表。</p><div style="font-size:12px;color:#72866c">列：AI SSD 需求同比增长；行：YMTC 产能（KWPM）</div><table class="matrix"><thead><tr><th>KWPM</th>${m.growth.map(g=>`<th>${g}%</th>`).join('')}</tr></thead><tbody>${m.values.map((r,i)=>`<tr><td class="rowhead">${m.capacity[i]}</td>${r.map((v,j)=>`<td><button aria-label="产能${m.capacity[i]}，需求增长${m.growth[j]}%，供需${v}%" data-matrix="${i},${j}" class="${i===matrixRow&&j===matrixCol?'picked':''}" style="background:${v<0?'rgba(200,119,104,'+(0.13+Math.abs(v)*.05)+')':'rgba(83,144,104,'+(0.09+v*.033)+')'}">${v>0?'+':''}${v}%</button></td>`).join('')}</tr>`).join('')}</tbody></table><div class="outcomes"><div><small>YMTC 产能</small><strong id="matrixCapacity"></strong><em>KWPM</em></div><div><small>AI SSD 需求增长</small><strong id="matrixGrowth"></strong><em>2028年同比</em></div><div><small>供需充足率</small><strong id="matrixValue"></strong><em id="matrixState"></em></div></div><div class="formula" id="matrixText"></div><div class="lab-foot">固定条件：非AI NAND需求同比+5%；其余供应商产能扩张沿用大摩团队预测。负值为不足，正值为过剩，0%为原表取整后的平衡附近。这里没有插值，也没有为情景赋予概率。</div>${refs([['ms',12]])}</div>`;updateMatrix()}
function updateMatrix(){let m=C.data.matrix,v=m.values[matrixRow][matrixCol],capacity=m.capacity[matrixRow],g=m.growth[matrixCol];document.getElementById('matrixCapacity').textContent=capacity;document.getElementById('matrixGrowth').textContent=g+'%';document.getElementById('matrixValue').textContent=signed(v,0);document.getElementById('matrixState').textContent=v<0?'不足':v>0?'过剩':'接近平衡';document.getElementById('matrixText').textContent=`在原表其他条件保持不变时，YMTC产能${capacity}KWPM、AI SSD需求增长${g}%的组合，对应${v<0?'供给缺口'+Math.abs(v)+'%':v>0?'供给过剩'+v+'%':'供需接近平衡'}。改变的是条件组合，不是一个确定的未来。`;document.querySelectorAll('[data-matrix]').forEach(x=>x.classList.toggle('picked',x.dataset.matrix===`${matrixRow},${matrixCol}`))}
function despecLab(){document.getElementById('labContent').innerHTML=`<div class="labbox"><h2>配置降低，总需求一定减少吗？</h2><p class="lede">用设备数量与单机容量两个变量，检验花旗和伯恩斯坦讨论的降配逻辑。</p><div class="lab-controls"><div class="control"><div class="slider-title"><label for="unitGrowth">设备数量变化</label><output id="unitGrowthVal"></output></div><input id="unitGrowth" aria-label="设备数量变化" type="range" min="-50" max="100" step="1" value="30"></div><div class="control"><div class="slider-title"><label for="contentGrowth">单机容量变化</label><output id="contentGrowthVal"></output></div><input id="contentGrowth" aria-label="单机容量变化" type="range" min="-50" max="50" step="1" value="-20"></div></div><div class="outcomes"><div><small>原始需求指数</small><strong>100</strong><em>教学基准</em></div><div><small>新需求指数</small><strong id="newIndex"></strong><em>设备数 × 单机容量</em></div><div><small>总需求变化</small><strong id="totalGrowth"></strong><em id="totalState"></em></div></div><div class="formula" id="despecFormula"></div><div class="lab-foot">所有参数均为教学示例。真实总需求还受客户结构、产品代际、重复统计和配置分布影响，不能由单一设备直接外推全行业。</div>${refs([['citi',9],['bernstein',4]])}</div>`;document.getElementById('unitGrowth').oninput=updateDespec;document.getElementById('contentGrowth').oninput=updateDespec;updateDespec()}
function updateDespec(){let u=+document.getElementById('unitGrowth').value,c=+document.getElementById('contentGrowth').value,n=(1+u/100)*(1+c/100)*100;document.getElementById('unitGrowthVal').textContent=signed(u,0);document.getElementById('contentGrowthVal').textContent=signed(c,0);document.getElementById('newIndex').textContent=fmt(n,1);document.getElementById('totalGrowth').textContent=signed(n-100,1);document.getElementById('totalState').textContent=n>100.01?'总量增加':n<99.99?'总量减少':'总量持平';document.getElementById('despecFormula').textContent=`100 × ${(1+u/100).toFixed(2)} × ${(1+c/100).toFixed(2)} = ${fmt(n,1)}。${c<0?'要完全抵消这一降配，设备数量至少需增长 '+fmt((1/(1+c/100)-1)*100,1)+'%。':'单机容量变化与设备数量共同决定总量。'}`}
function sources(){app.innerHTML=`<header class="pagehead"><div class="eyebrow">SOURCE READER</div><h1>原文随时可核对</h1><p>75 页原件按报告顺序保留，含研究正文、延伸阅读和披露。图表索引为全部 89 幅编号图表提供中文题名、读法与原文页码。</p></header><div class="segmented"><button data-source-tab="pages" class="${sourceTab==='pages'?'selected':''}">逐页研读</button><button data-source-tab="figures" class="${sourceTab==='figures'?'selected':''}">89 幅图表索引</button></div><div id="sourceContent"></div>`;if(sourceTab==='pages')renderReader('sourceContent',sourceId,sourcePage,false);else renderFigureIndex()}
function renderReader(id,s,p,modal){let guide=C.pageGuides[s][p-1],source=C.sources.find(x=>x.id===s);document.getElementById(id).innerHTML=`<div class="source-toolbar"><select aria-label="选择原始报告" class="reader-source" data-modal="${modal}">${C.sources.map(x=>`<option value="${x.id}" ${x.id===s?'selected':''}>${x.name} · ${x.pages}页</option>`).join('')}</select><select aria-label="选择原文页码" class="reader-page" data-modal="${modal}">${C.pageGuides[s].map(x=>`<option value="${x.page}" ${x.page===p?'selected':''}>p.${x.page} · ${x.title.slice(0,15)}</option>`).join('')}</select><button data-reader-step="-1" data-modal="${modal}" ${p===1?'disabled':''}>←</button><button data-reader-step="1" data-modal="${modal}" ${p===source.pages?'disabled':''}>→</button><button class="reader-zoom" data-modal="${modal}">放大图文</button></div><section class="page-note"><h3>${srcName[s]} · p.${p} / ${guide.title}</h3><p>${guide.note}</p>${guide.figs.length?`<p style="margin-top:8px">本页图表：${guide.figs.map(n=>`#${n}`).join(' · ')}</p>`:''}</section><div class="page-view"><img id="${modal?'modalPageImage':'sourcePageImage'}" src="${A.pages[s][p-1]}" alt="${source.name} 原文第${p}页"></div>`;
 const container=document.getElementById(id);container.querySelector('.reader-source').onchange=e=>updateReader(e.target.value,1,modal);container.querySelector('.reader-page').onchange=e=>updateReader(s,Number(e.target.value),modal);container.querySelectorAll('[data-reader-step]').forEach(b=>b.onclick=()=>updateReader(s,p+Number(b.dataset.readerStep),modal));container.querySelector('.reader-zoom').onclick=e=>{let im=document.getElementById(modal?'modalPageImage':'sourcePageImage');let big=im.style.width==='180%';im.style.width=big?'100%':'180%';e.target.textContent=big?'放大图文':'恢复适屏'};
}
function updateReader(s,p,modal){if(modal){modalSource=s;modalPage=p;renderReader('dialogBody',s,p,true);document.getElementById('dialogTitle').textContent=`${srcName[s]} · ${C.sources.find(x=>x.id===s).date}`}else{sourceId=s;sourcePage=p;renderReader('sourceContent',s,p,false)}}
function openSource(s,p){modalSource=s;modalPage=p;updateReader(s,p,true);const d=document.getElementById('sourceDialog');if(!d.open)d.showModal()}
function renderFigureIndex(){document.getElementById('sourceContent').innerHTML=`<input class="search" id="figureSearch" placeholder="检索图表：HBM、长鑫、合约、NAND、资本开支…" aria-label="检索图表"><div class="source-toolbar"><select id="figureFilter" aria-label="按机构筛选图表"><option value="all">三份报告 · 全部图表</option>${C.sources.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select><span id="figureCount" style="font-size:12px;color:#7d8e75"></span></div><div class="index-list" id="figureList"></div>`;document.getElementById('figureSearch').oninput=updateFigureList;document.getElementById('figureFilter').onchange=updateFigureList;updateFigureList()}
function updateFigureList(){const q=document.getElementById('figureSearch').value.toLowerCase(),s=document.getElementById('figureFilter').value;let arr=C.figures.filter(f=>(s==='all'||f.source===s)&&[f.title,f.note,srcName[f.source]].join(' ').toLowerCase().includes(q));document.getElementById('figureCount').textContent=`${arr.length} 幅`;document.getElementById('figureList').innerHTML=arr.map(f=>`<button class="index-row" data-source="${f.source}" data-page="${f.page}"><span class="code">${f.source==='bernstein'?'BERN.':f.source==='ms'?'MS':'CITI'} #${f.num}</span><div><h3>${f.title}</h3><p>${f.note}</p></div><span class="page">p.${f.page} ↗</span></button>`).join('')||'<p>没有匹配的图表，请换一个关键词。</p>'}
function review(){app.innerHTML=`<header class="pagehead"><div class="eyebrow">REVIEW & REFERENCE</div><h1>能解释，也能质疑</h1><p>先用自己的话回答，再展开解析。遇到陌生术语或不一致的数据，可以返回术语手册与原文核验记录。</p></header><div class="segmented">${[['qa','12 道思考题'],['terms','28 个术语'],['audit','原文核验记录']].map(x=>`<button data-review="${x[0]}" class="${reviewTab===x[0]?'selected':''}">${x[1]}</button>`).join('')}</div><div id="reviewContent"></div>`;if(reviewTab==='qa'){document.getElementById('reviewContent').innerHTML=C.questions.map((q,i)=>`<section class="qa"><div class="prompt-label">REFLECTION ${String(i+1).padStart(2,'0')}</div><h3>${q[0]}</h3><button data-answer="${i}" aria-expanded="false">展开解析</button><div class="answer" id="answer${i}" hidden>${q[1]}${refs([[q[2],q[3]]])}</div></section>`).join('')}
 if(reviewTab==='terms'){document.getElementById('reviewContent').innerHTML='<input id="termSearch" class="search" placeholder="搜索术语或中文解释…" aria-label="检索术语"><div class="glossary" id="termList"></div>';document.getElementById('termSearch').oninput=updateTerms;updateTerms()}
 if(reviewTab==='audit')document.getElementById('reviewContent').innerHTML='<div class="scope-note" style="margin-bottom:25px">以下区分原文陈述、按原始表格复算与跨机构口径。发现不一致，不意味着整份研究失效；也不据此擅自更改原文数据。</div>'+C.audits.map((a,i)=>`<section class="audit"><div class="eyebrow">CHECK ${String(i+1).padStart(2,'0')}</div><h3>${a[0]}</h3><p>${a[1]}</p><p class="audit-note">${a[2]}</p>${ref(a[3],a[4])}</section>`).join('')}
function updateTerms(){let q=document.getElementById('termSearch').value.toLowerCase();document.getElementById('termList').innerHTML=C.glossary.filter(g=>g.join(' ').toLowerCase().includes(q)).map(g=>`<section class="term"><small>${g[0]}</small><h3>${g[1]}</h3><p>${g[2]}</p>${refs([[g[3],g[4]]])}</section>`).join('')||'<p>没有匹配术语。</p>'}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.route){if(el.dataset.route==='course')lessonId=lastLesson;navigate(el.dataset.route)}if(el.dataset.lesson)gotoLesson(Number(el.dataset.lesson));if(el.dataset.source)openSource(el.dataset.source,Number(el.dataset.page));if(el.dataset.lab){labTab=el.dataset.lab;labs()}if(el.dataset.matrix){[matrixRow,matrixCol]=el.dataset.matrix.split(',').map(Number);updateMatrix()}if(el.dataset.sourceTab){sourceTab=el.dataset.sourceTab;sources()}if(el.dataset.review){reviewTab=el.dataset.review;review()}if(el.dataset.answer!==undefined){let a=document.getElementById('answer'+el.dataset.answer);a.hidden=!a.hidden;el.textContent=a.hidden?'展开解析':'收起解析';el.setAttribute('aria-expanded',String(!a.hidden))}});
document.getElementById('closeDialog').onclick=()=>document.getElementById('sourceDialog').close();document.getElementById('sourceDialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
progress();home();
